// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CiTypeDiscoveryConfig) predicate.CiTypeDiscoveryConfig {
	return predicate.CiTypeDiscoveryConfig(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
